{
  "candidate_feasibility": "Every condition must converge and satisfy the terminal windows; minimum margin and maxima over all conditions must obey all four limits.",
  "freeze_decision": "FREEZE_FOR_PROTOTYPE",
  "gravity_m_s2": 9.80665,
  "maximum_crossload_n": 0.18,
  "maximum_electrical_power_w": 440.0,
  "maximum_pressure_recovery_index": 1.25,
  "minimum_net_thrust_margin_n": 3.2,
  "pareto_objectives": [
    "minimize maximum electrical_power_w",
    "maximize minimum net_thrust_margin_n",
    "minimize maximum pressure_recovery_index"
  ],
  "per_condition_formulas": {
    "axial_drag_n": "corrected_drag_coefficient*dynamic_pressure_pa*physical_reference_area_m2",
    "corrected_drag_coefficient": "max(CD,0)*tunnel_drag_factor",
    "corrected_sideforce_coefficient": "abs(CL)*tunnel_sideforce_factor",
    "crossload_n": "corrected_sideforce_coefficient*dynamic_pressure_pa*physical_reference_area_m2",
    "dynamic_pressure_pa": "0.5*density_kg_m3*velocity_m_s^2",
    "electrical_power_w": "base_electrical_power_w+axial_drag_n*velocity_m_s/propulsive_efficiency",
    "net_thrust_margin_n": "available_rotor_thrust_n-required_vehicle_thrust_n-(installed_mass_g / 1000)*gravity_m_s2-axial_drag_n",
    "pressure_recovery_index": "(max(surface Pressure)-min(surface Pressure))+tunnel_recovery_offset"
  },
  "propulsive_efficiency": 0.65,
  "schema_version": "1.0",
  "selection_tie_break": [
    "feasible candidates only",
    "minimum maximum electrical_power_w",
    "maximum minimum net_thrust_margin_n",
    "minimum maximum pressure_recovery_index",
    "candidate_id ascending"
  ],
  "violation_codes": [
    {
      "code": "NOT_CONVERGED",
      "trigger": "any condition whose rms_pressure is above the convergence_residual_rms_pressure_max limit"
    },
    {
      "code": "UNSTABLE_TERMINAL_WINDOW",
      "trigger": "any condition whose terminal_cd_range or terminal_cl_range is above the maximum_terminal_cd_range or maximum_terminal_cl_range limit"
    },
    {
      "code": "THRUST_MARGIN",
      "trigger": "the candidate's minimum_net_thrust_margin_n is below the minimum_net_thrust_margin_n limit"
    },
    {
      "code": "CROSSLOAD",
      "trigger": "the candidate's maximum_crossload_n is above the maximum_crossload_n limit"
    },
    {
      "code": "PRESSURE_RECOVERY",
      "trigger": "the candidate's maximum_pressure_recovery_index is above the maximum_pressure_recovery_index limit"
    },
    {
      "code": "POWER",
      "trigger": "the candidate's maximum_electrical_power_w is above the maximum_electrical_power_w limit"
    }
  ],
  "violations_rule": "Record every violation_codes entry that applies to the candidate, each at most once; order is not significant. A candidate is feasible only when its list is empty."
}

